import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"TLS, authentication and permissions","description":"","frontmatter":{"pageId":"admins/security-auth","contentRevision":2},"headers":[],"relativePath":"en/admins/security-auth.md","filePath":"en/admins/security-auth.md"}'),r={name:"en/admins/security-auth.md"};function s(o,e,d,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="tls-authentication-and-permissions" tabindex="-1">TLS, authentication and permissions <a class="header-anchor" href="#tls-authentication-and-permissions" aria-label="Permalink to &quot;TLS, authentication and permissions&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>TLS is enabled by default. Set PEM CertificatePath/KeyPath or use a self-signed certificate; distribute its pin through an independent channel. SelfSignedPath selects the self-signed certificate path. Plan certificate rotation in advance.</p><p>Steam authentication requires SteamWebApiKey and administrative Steam IDs as appropriate. AllowPassword enables password accounts; AdminLogins assigns initial administrators. ServerPassword is not a replacement for personal authentication.</p><p>Give each integration a separate Admin:Tokens entry with Name, Token and Scopes. Names are unique, [a-z0-9-], up to 32 characters; tokens are unique and at least 24 characters. read reads, moderate includes read, chat permits external chat, and admin grants all permissions. Minimize scope.</p><h2 id="rotate-access" tabindex="-1">Separate and revoke integration access <a class="header-anchor" href="#rotate-access" aria-label="Permalink to &quot;Separate and revoke integration access {#rotate-access}&quot;">​</a></h2><p>Give monitoring read, a chat bridge read+chat, and moderation moderate only as needed. moderate includes read but not chat; admin grants everything. Use a distinct name/secret per process. Revoke independently, apply configuration through controlled restart and verify the revoked token fails.</p><p>Only legacy Admin:ApiToken opens the panel; a named admin-scope token still does not. Restart ends cookie sessions. Cookie mutations require X-Rimlink-Panel: 1 and an acceptable Origin; Bearer integrations must not emulate cookies.</p><p>Never send tokens in URLs. CLI --token can remain in history/process lists: use a protected operator environment and keep command transcripts private.</p><h2 id="rotate-cert" tabindex="-1">Planned certificate replacement <a class="header-anchor" href="#rotate-cert" aria-label="Permalink to &quot;Planned certificate replacement {#rotate-cert}&quot;">​</a></h2><p>Preserve working settings and announce the new pin through a trusted channel before replacement. After restart compare the served certificate and test game clients/bot. A stored old pin must require a decision, not update silently.</p><p>For an unexpected pin, inspect address/NAT/proxy and whether rotation really occurred. Never tell everyone to use --insecure or trust arbitrary certificates. The default SelfSignedPath depends on DataDir; an empty mount can look like certificate rotation on a new server.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The panel uses legacy Admin:ApiToken, not named tokens. Its cookie is HttpOnly/Secure/SameSite=Strict; in-memory sessions end on restart; 5 failures lock an IP for 10 minutes. Cookie mutations require CSRF. Do not use --insecure outside an isolated test. X-Rimlink-Actor is a 1–64-character audit label without controls, not proof of identity.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./api">REST API reference</a></li><li><a href="./administration">Panel and moderation</a></li><li><a href="./discord">Discord bot</a></li></ul>',17)])])}const m=a(r,[["render",s]]);export{h as __pageData,m as default};
